(() => {
  const links = [...document.querySelectorAll('.season-link')];
  const targets = [
    { id: 'inicio', cls: 'season-halloween' },
    { id: 'bailes', cls: 'season-folk' },
    { id: 'navidad', cls: 'season-christmas' }
  ];
  const setActive = (cls) => links.forEach(a => a.classList.toggle('is-active', a.classList.contains(cls)));
  const observer = new IntersectionObserver(entries => {
    entries.filter(e => e.isIntersecting).forEach(e => {
      const item = targets.find(t => t.id === e.target.id);
      if (item) setActive(item.cls);
    });
  }, {rootMargin:'-20% 0px -65% 0px', threshold:0});
  targets.forEach(t => { const el = document.getElementById(t.id); if (el) observer.observe(el); });
})();

(function(){
  const stage=document.querySelector('.halloween-3d-stage');
  const model=document.querySelector('.halloween-3d-model');
  if(!stage||!model) return;
  let timer, dragging=false, startX=0, lastX=0, theta=0, horizontalDrag=false, didDrag=false;
  const getTheta=()=>{
    const orbit=(model.getAttribute('camera-orbit')||'0deg 82deg 105%').split(/\s+/);
    const raw=parseFloat(orbit[0]);
    return Number.isFinite(raw)?raw:0;
  };
  theta=getTheta();
  const setTheta=()=>{
    model.setAttribute('camera-orbit', `${theta}deg 82deg 105%`);
  };
  stage.addEventListener('pointerdown',e=>{
    if(e.pointerType==='mouse' && e.button!==0) return;
    dragging=true; horizontalDrag=false; didDrag=false; startX=lastX=e.clientX;
    stage.setPointerCapture?.(e.pointerId);
  });
  stage.addEventListener('pointermove',e=>{
    if(!dragging) return;
    const dx=e.clientX-lastX;
    const totalX=e.clientX-startX;
    if(Math.abs(totalX)>8 || Math.abs(e.clientY-(stage._startY??e.clientY))>8) didDrag=true;
    if(Math.abs(totalX)>6) horizontalDrag=Math.abs(totalX)>Math.abs(e.clientY-(stage._startY??e.clientY));
    if(Math.abs(totalX)>6 && Math.abs(totalX)>Math.abs((e.clientY-(stage._startY??e.clientY)))) e.preventDefault();
    if(horizontalDrag){
      theta-=dx*0.55;
      if(theta>180) theta-=360;
      if(theta<-180) theta+=360;
      setTheta();
    }
    lastX=e.clientX;
  });
  stage.addEventListener('pointerdown',e=>{stage._startY=e.clientY;});
  const endDrag=e=>{
    dragging=false; horizontalDrag=false;
    try{stage.releasePointerCapture?.(e.pointerId)}catch(_){}
  };
  stage.addEventListener('pointerup',endDrag);
  stage.addEventListener('pointercancel',endDrag);
  const pop=()=>{
    stage.classList.remove('is-popping');
    void stage.offsetWidth;
    stage.classList.add('is-popping');
    clearTimeout(timer);
    timer=setTimeout(()=>stage.classList.remove('is-popping'),760);
  };
  const video=document.getElementById('cat-video');
  let videoReady=false;
  const showModel=()=>{ stage.classList.remove('is-video'); try{video.pause();}catch(_){} };
  if(video){
    video.loop=true;
    video.addEventListener('canplay',()=>{ videoReady=true; },{once:true});
    video.addEventListener('error',()=>{ videoReady=false; showModel(); });
    const loadVideo=()=>{ if(!video.getAttribute('src')){ video.src=video.dataset.src; video.load(); } };
    const idle=window.requestIdleCallback||(fn=>setTimeout(fn,1500));
    if(document.readyState==='complete') idle(loadVideo); else addEventListener('load',()=>idle(loadVideo),{once:true});
    new IntersectionObserver(entries=>{
      entries.forEach(en=>{
        if(!stage.classList.contains('is-video')) return;
        if(en.isIntersecting){ const pr=video.play(); if(pr&&pr.catch) pr.catch(()=>{}); }
        else video.pause();
      });
    },{threshold:0.1}).observe(stage);
  }
  const showVideo=()=>{
    if(!video||!videoReady) return false;
    video.currentTime=0;
    const pr=video.play();
    stage.classList.add('is-video');
    if(pr&&pr.catch) pr.catch(showModel);
    return true;
  };
  const toggle=()=>{
    if(stage.classList.contains('is-video')){ showModel(); pop(); return; }
    if(!showVideo()) pop();
  };
  let downOK=false, lastToggle=0;
  stage.addEventListener('pointerdown',e=>{ downOK = !(e.pointerType==='mouse' && e.button!==0); });
  stage.addEventListener('pointerup',e=>{
    if(!downOK) return;
    downOK=false;
    if(didDrag) return;
    const r=stage.getBoundingClientRect();
    if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom) return;
    lastToggle=performance.now();
    toggle();
  });
  stage.addEventListener('pointercancel',()=>{ downOK=false; });
  stage.addEventListener('contextmenu',e=>e.preventDefault());
  stage.addEventListener('click',()=>{
    if(performance.now()-lastToggle<800){ return; }
    if(didDrag){ didDrag=false; return; }
    toggle();
  });
  stage.addEventListener('keydown',e=>{
    if(e.key==='Enter'||e.key===' '){e.preventDefault();toggle();}
  });
})();

(function(){
  const selectors = [
    '.season-hero *',
    '.hero-social-link',
    '.halloween-3d-stage',
    '.halloween-3d-model',
    '.halloween-particle'
  ];
  const elements = [...new Set(selectors.flatMap(sel => [...document.querySelectorAll(sel)]))];
  if(!elements.length) return;
  const observer = new IntersectionObserver(entries => {
    entries.forEach(entry => {
      const el = entry.target;
      if(entry.isIntersecting){
        el.classList.remove('kalu-animation-paused');
      }else{
        el.classList.add('kalu-animation-paused');
      }
    });
  }, {threshold:0, rootMargin:'80px 0px 80px 0px'});
  elements.forEach(el => observer.observe(el));
  const model = document.querySelector('.halloween-3d-model');
  if(model){
    const syncModel = entry => {
      if(entry.isIntersecting){
        model.setAttribute('auto-rotate','');
      }else{
        model.removeAttribute('auto-rotate');
      }
    };
    const modelObserver = new IntersectionObserver(entries => entries.forEach(syncModel), {threshold:0, rootMargin:'80px 0px 80px 0px'});
    modelObserver.observe(model);
  }
})();

/* KALU — imágenes: se usa lazy loading nativo del navegador; no se reemplazan los src. */
/* KALÚ — navegación de catálogos + filtros por sección: robusto en PC y móvil */
(function(){
  const sectionIds = ['mascaras','accesorios','sombreros-catalogo','pelucas','alquiler','tipicos-baile'];
  const sections = sectionIds.map(id => document.getElementById(id)).filter(Boolean);
  const catalogShell = document.getElementById('catalogo-ventanas');
  const catalogTabs = catalogShell ? Array.from(catalogShell.querySelectorAll('.catalog-window-tab')) : [];

  const activateSection = (id, opts={}) => {
    const target = document.getElementById(id);
    if (!target || !sectionIds.includes(id)) return;
    if (catalogTabs.length) {
      catalogTabs.forEach(tab => {
        const on = tab.dataset.catalogTarget === id;
        tab.classList.toggle('is-active', on);
        tab.setAttribute('aria-selected', String(on));
        tab.tabIndex = on ? 0 : -1;
      });
      sections.forEach(section => {
        const on = section.id === id;
        if (on && window.kaluLoadCatalogImages) window.kaluLoadCatalogImages(section);
        section.classList.toggle('catalog-window-active', on);
        section.classList.toggle('catalog-window-hidden', !on);
        section.hidden = !on;
      });
    } else if (window.kaluLoadCatalogImages) {
      window.kaluLoadCatalogImages(target);
    }
    if (opts.scroll && catalogShell && !opts.fromLink) {
      catalogShell.scrollIntoView({behavior:'smooth', block:'start'});
    }
    const activeTab = catalogTabs.find(t => t.dataset.catalogTarget === id);
    if (activeTab && opts.centerTab) activeTab.scrollIntoView({behavior:'smooth', inline:'center', block:'nearest'});
  };

  catalogTabs.forEach(tab => {
    tab.addEventListener('click', () => activateSection(tab.dataset.catalogTarget, {centerTab:true}));
    tab.addEventListener('keydown', e => {
      if (!['ArrowRight','ArrowLeft','Home','End'].includes(e.key)) return;
      e.preventDefault();
      let i = catalogTabs.indexOf(tab);
      if (e.key === 'ArrowRight') i = (i + 1) % catalogTabs.length;
      if (e.key === 'ArrowLeft') i = (i - 1 + catalogTabs.length) % catalogTabs.length;
      if (e.key === 'Home') i = 0;
      if (e.key === 'End') i = catalogTabs.length - 1;
      catalogTabs[i].focus();
      activateSection(catalogTabs[i].dataset.catalogTarget, {centerTab:true});
    });
  });

  const rentalTabs = Array.from(document.querySelectorAll('.rental-window-tab'));
  const rentalGroups = Array.from(document.querySelectorAll('#alquiler .rental-group'));
  const activateRental = (id, center=true) => {
    rentalTabs.forEach(tab => {
      const on = tab.dataset.rentalTarget === id;
      tab.classList.toggle('is-active', on);
      tab.setAttribute('aria-selected', String(on));
      tab.tabIndex = on ? 0 : -1;
      if (on && center) tab.scrollIntoView({behavior:'smooth', inline:'center', block:'nearest'});
    });
    rentalGroups.forEach(group => {
      const on = group.dataset.rentalWindow === id;
      if (on && window.kaluLoadCatalogImages) window.kaluLoadCatalogImages(group);
      group.classList.toggle('catalog-window-active', on);
      group.classList.toggle('catalog-window-hidden', !on);
      group.hidden = !on;
    });
    // Al cambiar de edad, reinicia su filtro para evitar estados cruzados.
    const activeGroup = rentalGroups.find(group => group.dataset.rentalWindow === id);
    if (activeGroup) {
      const first = activeGroup.querySelector('.section-filter-pill');
      if (first) applyFilter(first, {scroll:false});
    }
  };
  rentalTabs.forEach(tab => {
    tab.addEventListener('click', () => activateRental(tab.dataset.rentalTarget));
  });

  const getFilterCards = nav => {
    const group = nav.closest('.rental-group') || nav.closest('section');
    if (!group) return {group:null, cards:[]};
    return {group, cards:Array.from(group.querySelectorAll('article.card[data-code]'))};
  };

  const setFilterState = (nav, button) => {
    nav.querySelectorAll('.section-filter-pill').forEach(b => {
      const active = b === button;
      b.classList.toggle('is-active', active);
      b.setAttribute('aria-selected', String(active));
    });
  };

  function applyFilter(button, opts={}) {
    if (!button) return;
    const nav = button.closest('.section-filter');
    if (!nav) return;
    const value = button.dataset.filterValue || '';
    const attr = nav.dataset.filterAttr || 'data-category';
    const {group, cards} = getFilterCards(nav);
    if (!group) return;
    setFilterState(nav, button);

    let visible = 0;
    cards.forEach(card => {
      const cardValue = (card.getAttribute(attr) || '').trim();
      const show = !value || cardValue === value;
      card.hidden = !show;
      card.setAttribute('aria-hidden', String(!show));
      if (show) visible++;
    });

    let status = nav.querySelector('.section-filter-status');
    if (!status) {
      status = document.createElement('span');
      status.className = 'section-filter-status';
      status.setAttribute('aria-live','polite');
      nav.appendChild(status);
    }
    status.textContent = `${visible} ${visible === 1 ? 'producto' : 'productos'}`;

    const grid = group.querySelector('.grid');
    if (opts.scroll !== false && grid && grid.scrollWidth > grid.clientWidth) {
      grid.scrollTo({left:0, behavior:'smooth'});
    }
  }

  const bindFilterList = list => {
    if (!list || list.dataset.kaluFilterBound === '1') return;
    list.dataset.kaluFilterBound = '1';
    list.style.touchAction = 'pan-x';
    list.addEventListener('click', e => {
      const button = e.target.closest('.section-filter-pill');
      if (!button || !list.contains(button)) return;
      applyFilter(button);
    });
    // Fallback táctil sin cancelar el click nativo.
    let lastPointer = 0;
    list.addEventListener('pointerup', e => {
      const button = e.target.closest('.section-filter-pill');
      if (!button || !list.contains(button)) return;
      if (e.pointerType === 'touch' || e.pointerType === 'pen') {
        const now = performance.now();
        if (now - lastPointer > 350) {
          lastPointer = now;
          applyFilter(button, {scroll:false});
        }
      }
    }, {passive:true});
  };

  document.querySelectorAll('.section-filter-list').forEach(bindFilterList);
  document.querySelectorAll('.section-filter-pill').forEach(button => {
    button.addEventListener('keydown', e => {
      if (e.key !== 'Enter' && e.key !== ' ') return;
      e.preventDefault();
      applyFilter(button);
    });
  });

  // Abrir la ventana correcta desde enlaces internos cuando el componente exista.
  document.addEventListener('click', e => {
    const link = e.target.closest('a[href^="#"]');
    if (!link) return;
    const id = link.getAttribute('href').slice(1);
    if (sectionIds.includes(id)) activateSection(id, {fromLink:true, centerTab:true});
  }, true);

  if (typeof focusCard === 'function') {
    const originalFocusCard = focusCard;
    focusCard = function(card){
      const owner = card && card.closest ? card.closest('section[id]') : null;
      if (owner && sectionIds.includes(owner.id)) activateSection(owner.id, {fromLink:true, centerTab:true});
      const rental = card && card.closest ? card.closest('.rental-group') : null;
      if (rental && rental.dataset.rentalWindow) activateRental(rental.dataset.rentalWindow, false);
      originalFocusCard(card);
    };
  }

  // Inicialización sin exigir un contenedor de ventanas.
  if (catalogTabs.length && sections.length) activateSection('mascaras', {centerTab:false});
  if (rentalTabs.length) activateRental(rentalTabs[0]?.dataset.rentalTarget || 'alquiler-nino', false);

  // Estado inicial de cada filtro + evita cargar contenido de secciones no activas si aplica.
  document.querySelectorAll('.section-filter').forEach(nav => {
    const first = nav.querySelector('.section-filter-pill');
    if (first) applyFilter(first, {scroll:false});
  });
})();

/* KALÚ professional UX layer: product modal + horizontal carousels. */
(() => {
  const $ = (s, r=document) => r.querySelector(s);
  const $$ = (s, r=document) => [...r.querySelectorAll(s)];
  const dialog = $('#kalu-product-dialog');
  if (dialog) {
    const image = $('#kalu-product-image'), title = $('#kalu-product-title'), code = $('#kalu-product-code'), desc = $('#kalu-product-description'), cat = $('#kalu-product-category'), wa = $('#kalu-product-wa'), add = $('#kalu-product-add');
    let activeCard = null;
    const escText = (v) => String(v || '').trim();
    const productFromCard = (card) => ({
      name: escText(card.dataset.name || $('h3',card)?.textContent),
      code: escText(card.dataset.code || $('.code',card)?.textContent),
      image: escText(card.dataset.image || $('img',card)?.getAttribute('src')),
      desc: escText(card.dataset.desc || $('p',card)?.textContent),
      category: escText(card.dataset.category || 'Producto Kalú')
    });
    const openProduct = (card) => {
      const p = productFromCard(card); activeCard = card;
      image.src = p.image; image.alt = p.name; title.textContent = p.name; code.textContent = p.code; desc.textContent = p.desc || 'Consulta disponibilidad y precio.'; cat.textContent = p.category || 'Producto Kalú';
      const msg = `Hola Kalú, quiero consultar por ${p.name} (${p.code}).`;
      const numero = /^DF|^TB/.test(p.code) ? '573215055733' : '573117570138';
      wa.href = `https://wa.me/${numero}?text=${encodeURIComponent(msg)}`;
      if (typeof dialog.showModal === 'function') dialog.showModal(); else dialog.setAttribute('open','');
    };
    $('#kalu-product-close')?.addEventListener('click',()=>dialog.close());
    dialog.addEventListener('click',e=>{ if(e.target===dialog) dialog.close(); });
    $$('.card[data-kalu-product]').forEach(card => {
      card.addEventListener('click', e => {
        if (e.target.closest('button,a,input,select,textarea')) return;
        openProduct(card);
      });
    });
    add?.addEventListener('click',()=>{
      const btn = activeCard?.querySelector('.mini-button');
      if (btn) { btn.click(); add.textContent='✓ Agregado a mi selección'; setTimeout(()=>add.textContent='＋ Agregar a mi selección',1200); }
    });
  }

  const tracks = $$('.business-line .grid');
  const updateButtons = (track, prev, next) => {
    const max = Math.max(0, track.scrollWidth - track.clientWidth - 2);
    prev.disabled = track.scrollLeft <= 2;
    next.disabled = track.scrollLeft >= max;
    prev.classList.toggle('is-disabled', prev.disabled);
    next.classList.toggle('is-disabled', next.disabled);
  };

  tracks.forEach(track => {
    if (track.dataset.kaluCarouselReady) return;
    track.dataset.kaluCarouselReady='1';
    track.classList.add('kalu-carousel-track');

    const shell=document.createElement('div');
    shell.className='kalu-carousel-shell';
    track.parentNode.insertBefore(shell,track);
    shell.appendChild(track);

    const controls=document.createElement('div');
    controls.className='kalu-carousel-controls';
    controls.setAttribute('aria-label','Controles del carrusel');
    const prev=document.createElement('button');
    prev.className='kalu-carousel-corner-btn is-prev';
    prev.type='button';
    prev.setAttribute('aria-label','Productos anteriores');
    prev.innerHTML='‹';
    const next=document.createElement('button');
    next.className='kalu-carousel-corner-btn is-next';
    next.type='button';
    next.setAttribute('aria-label','Productos siguientes');
    next.innerHTML='›';
    controls.append(prev,next);
    shell.appendChild(controls);

    const toolbar=document.createElement('div');
    toolbar.className='kalu-carousel-toolbar';
    const view=document.createElement('button');
    view.className='kalu-view-all';
    view.type='button';
    view.textContent='Ver todo';
    toolbar.appendChild(view);
    shell.insertBefore(toolbar,track);

    const step=()=>Math.max(track.clientWidth*.82,220);
    prev.addEventListener('click',()=>track.scrollBy({left:-step(),behavior:'smooth'}));
    next.addEventListener('click',()=>track.scrollBy({left:step(),behavior:'smooth'}));
    view.addEventListener('click',()=>{
      const expanded=track.classList.toggle('is-expanded');
      view.textContent=expanded?'Ver carrusel':'Ver todo';
      controls.hidden=expanded;
      requestAnimationFrame(()=>updateButtons(track,prev,next));
    });
    track.addEventListener('scroll',()=>updateButtons(track,prev,next),{passive:true});
    window.addEventListener('resize',()=>updateButtons(track,prev,next),{passive:true});
    requestAnimationFrame(()=>updateButtons(track,prev,next));
  });
})();
